insert into legendary_moments
  (player_match, archetype, trigger, bonus, narration)
values
  ('Payet', 'ARTISTE', 'vs_lyon', 10, ARRAY['Payet decide une nouvelle fois de torturer Lyon.', 'Payet rappelle pourquoi Marseille l''adore : un geste, et tout bascule.', 'Coup franc enroule, lucarne. Payet humilie Lyon une fois de plus.']::text[]),
  ('Payet', 'ARTISTE', 'big_match', 8, ARRAY['Payet rappelle pourquoi Marseille l''adore.', 'Dans les grands rendez-vous, Payet sort le grand jeu.']::text[]),
  ('Juninho', 'TIREUR D''ELITE', 'free_kick', 14, ARRAY['Le mur sait deja que c''est termine.', 'Le mur est la pour la decoration. Juninho arme sa feuille morte.', 'Juninho marque un coup franc venu d''un autre monde.']::text[]),
  ('Hazard', 'GENIE', 'decisive', 10, ARRAY['Hazard danse entre les defenseurs.', 'Hazard se met sur son pied gauche, et plus personne ne respire.', 'Trois defenseurs, trois statues. Hazard les a tous effaces.']::text[]),
  ('Mbappe', 'FUSEE', 'counter_attack', 11, ARRAY['Les defenseurs savent deja qu''ils sont battus.', 'Mbappe crucifie la defense sur une acceleration fulgurante.', 'Lance en profondeur, Mbappe a deja vingt metres d''avance.']::text[]),
  ('Drogba', 'MONSTRE', 'stakes', 10, ARRAY['Drogba transforme le match en combat. Et il gagne ses combats.', 'Un appui, une frappe : Drogba ne tremble jamais dans les grands soirs.']::text[]),
  ('Pauleta', 'RENARD', 'box', 9, ARRAY['Une occasion suffit a Pauleta.', 'Pauleta etait la ou il fallait, comme toujours.']::text[]),
  ('Ben Arfa', 'CHAOS', 'blocked_match', 12, ARRAY['Ben Arfa decide de jouer seul. Et il a raison.', 'Ben Arfa part de son camp, elimine la moitie de l''equipe et conclut.']::text[]),
  ('Ibrahimovic', 'ROI', 'level_gap', 12, ARRAY['Zlatan considere ce match comme son terrain d''entrainement.', 'Zlatan rappelle qui est le patron, d''un geste impossible.']::text[]),
  ('Gourcuff', 'ARTISTE', 'prestige', 9, ARRAY['Pendant quelques instants, Bordeaux redevient magique.', 'Gourcuff caresse le ballon comme au printemps 2009.']::text[]),
  ('Nene', 'MAGICIEN', 'set_piece', 9, ARRAY['Nene depose le ballon et signe un chef-d''oeuvre.']::text[]),
  ('Niang', 'GUERRIER', 'big_match', 8, ARRAY['Niang plante les crampons et arrache le but du guerrier.']::text[]),
  ('Lopez', 'TUEUR', 'end_of_match', 9, ARRAY['En fin de match, Lisandro Lopez ne pardonne jamais.', 'Lisandro surgit dans le money time : l''Argentin a le sens du timing.']::text[]),
  ('Ronaldinho', 'SORCIER', 'big_match', 13, ARRAY['Ronaldinho transforme le Parc en terrain de jeu, sourire aux levres.', 'Elastico, sombrero, et le ballon finit au fond : Ronaldinho regale.', 'Ronaldinho invente un geste que personne n''avait jamais vu.']::text[]),
  ('Ronaldinho', 'SORCIER', 'free_kick', 11, ARRAY['Coup franc brosse de Ronaldinho, le gardien reste cloue.']::text[]),
  ('Giuly', 'LUTIN', 'counter_attack', 9, ARRAY['Giuly file comme un lutin et trompe le gardien.', 'Le petit Giuly se faufile partout : impossible a attraper.']::text[]),
  ('Morientes', 'RENARD', 'box', 9, ARRAY['Morientes prend le dessus dans les airs : but du renard.']::text[]),
  ('Gignac', 'GUERRIER', 'big_match', 9, ARRAY['Gignac repond toujours present dans les grands soirs.', 'Une truelle de Gignac, et le Velodrome explose.']::text[]),
  ('Lacazette', 'RENARD', 'decisive', 8, ARRAY['Lacazette n''a besoin que d''un ballon pour faire la difference.']::text[]),
  ('Pjanic', 'TIREUR D''ELITE', 'free_kick', 11, ARRAY['Pjanic arme un coup franc soyeux, droit dans la lucarne.']::text[]);
